#!/usr/bin/env python3
"""Bulk-teach Mirror from a JSONL file (e.g. generated by ChatGPT).

Usage:
    .venv\\Scripts\\python.exe teach_dataset.py my_data.jsonl [more.jsonl ...]

Each line: {"question": "...", "answer": "...", "domain": "physics", "trust_tier": 2}
Lines are validated, cleaned and de-duplicated before streaming into the vault.
"""
import argparse
import hashlib
import json
import re
import sys
import tempfile
from pathlib import Path

if hasattr(sys.stdout, "reconfigure"):
    sys.stdout.reconfigure(encoding="utf-8")

RESTORE_ROOT = Path(__file__).resolve().parents[2]
if str(RESTORE_ROOT) not in sys.path:
    sys.path.insert(0, str(RESTORE_ROOT))

from mirror_crystal import DiskCrystalVault

def require_existing_sqlite_vault(path: Path) -> Path:
    """Refuse to create a new empty database or treat MCRYSTAL as SQLite."""
    resolved = path.expanduser().resolve()
    if not resolved.is_file():
        raise FileNotFoundError(
            f"Production .dcrystal vault not found: {resolved}. "
            "Pass the actual existing SQLite vault with --vault."
        )
    with resolved.open("rb") as handle:
        header = handle.read(16)
    if header != b"SQLite format 3\x00":
        raise ValueError(
            f"Not a SQLite .dcrystal vault: {resolved}. "
            "Do not rename or open a .mcrystal artifact as .dcrystal."
        )
    return resolved


BAD_ANSWER = re.compile(r"(as an ai|i cannot|i'm sorry|lorem ipsum|\[insert)", re.I)


def clean(path: Path, seen: set) -> tuple[list[dict], dict]:
    rows, stats = [], {"read": 0, "kept": 0, "bad_json": 0, "invalid": 0, "duplicate": 0}
    for line in path.open(encoding="utf-8-sig", errors="replace"):
        line = line.strip().rstrip(",")
        if not line or line in ("[", "]"):
            continue
        stats["read"] += 1
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            stats["bad_json"] += 1
            continue
        q = str(obj.get("question") or obj.get("prompt") or "").strip()
        a = str(obj.get("answer") or obj.get("response") or "").strip()
        if len(q) < 8 or len(a) < 2 or len(a) > 6000 or BAD_ANSWER.search(a):
            stats["invalid"] += 1
            continue
        key = hashlib.sha1(re.sub(r"\W+", " ", q.lower()).strip().encode()).hexdigest()
        if key in seen:
            stats["duplicate"] += 1
            continue
        seen.add(key)
        rows.append({
            "question": q,
            "response": a,
            "domain": str(obj.get("domain", "taught_dataset"))[:64],
            "trust_tier": int(obj.get("trust_tier", 2)),
        })
        stats["kept"] += 1
    return rows, stats


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Teach an existing Mirror SQLite .dcrystal vault from deduplicated JSONL files."
    )
    parser.add_argument("--vault", required=True, type=Path,
                        help="Path to the existing SQLite .dcrystal file; it will not be created.")
    parser.add_argument("files", nargs="+", type=Path, help="JSONL training files.")
    args = parser.parse_args()

    vault_path = require_existing_sqlite_vault(args.vault)
    for path in args.files:
        if not path.is_file():
            raise FileNotFoundError(f"Dataset file not found: {path}")

    vault = DiskCrystalVault(vault_path)
    try:
        before = vault.rule_count()
        seen: set = set()
        for file_path in args.files:
            rows, stats = clean(file_path, seen)
            print(f"{file_path.name}: {stats}")
            if not rows:
                continue
            with tempfile.NamedTemporaryFile("w", suffix=".jsonl", delete=False, encoding="utf-8") as tmp:
                temp_path = Path(tmp.name)
                for row in rows:
                    tmp.write(json.dumps(row, ensure_ascii=False) + "\n")
            try:
                result = vault.ingest_jsonl(temp_path)
            finally:
                temp_path.unlink(missing_ok=True)
            print(f"  -> ingested: {result}")
        after = vault.rule_count()
        print(f"\nVault rules: {before:,} -> {after:,}")
    finally:
        vault.close()


if __name__ == "__main__":
    main()



